const workflow = $node['Create Cloned Workflow'].json;
const credential = $node['Create Dynamic Google OAuth Credential'].json;

const credentialKeyMap = {
  'n8n-nodes-base.gmail': 'gmailOAuth2',
  'n8n-nodes-base.gmailTrigger': 'gmailOAuth2',
  'n8n-nodes-base.googleSheets': 'googleSheetsOAuth2Api',
  'n8n-nodes-base.googleDrive': 'googleDriveOAuth2Api',
  'n8n-nodes-base.googleCalendar': 'googleCalendarOAuth2Api'
};

const updatedNodes = (workflow.nodes || []).map(node => {
  const key = credentialKeyMap[node.type];
  if (key) {
    if (!node.credentials) node.credentials = {};
    node.credentials[key] = { id: credential.id, name: credential.name };
  }
  return node;
});

return [{
  json: {
    id: workflow.id,
    workflowId: workflow.id,
    updatedWorkflow: {
      name: workflow.name,
      nodes: updatedNodes,
      connections: workflow.connections,
      settings: workflow.settings
    },
    credentialId: credential.id
  }
}];

const workflowName = $node['Detect Google Nodes & Scopes'].json.workflowName;
const scopes = $node['Detect Google Nodes & Scopes'].json.scopes || '';

const serviceTypeMap = {
  gmail: 'gmailOAuth2',
  googlesheets: 'googleSheetsOAuth2Api',
  googledrive: 'googleDriveOAuth2Api',
  googlecalendar: 'googleCalendarOAuth2Api'
};

let credentialType = 'googleOAuth2Api';
const googleNodes = $json.nodes || [];
googleNodes.forEach(n => {
  for (const key in serviceTypeMap) {
    if (n.type.toLowerCase().includes(key)) {
      credentialType = serviceTypeMap[key];
      break;
    }
  }
});

const refreshToken = $json.body?.refreshToken || $json.refreshToken || $json.oauthToken;

return [{
  json: {
    credentialPayload: {
      name: `Dynamic Google OAuth2 - ${workflowName}`,
      type: credentialType,
      data: {
        clientId: '353816148637-6cvk28f15u47073vdlphts24qof3rmne.apps.googleusercontent.com',
        clientSecret: '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',
        refreshToken: refreshToken,
        scope: scopes,
        sendAdditionalBodyProperties: true,
        additionalBodyProperties: {}
      }
    }
  }
}];

// Detect Google nodes and combine scopes
const workflow = $json;
const googleNodes = (workflow.nodes || []).filter(n => 
  ['gmail', 'googlesheets', 'googledrive', 'googlecalendar'].some(service => n.type.toLowerCase().includes(service))
);

const scopeMap = {
  gmail: 'https://www.googleapis.com/auth/gmail.readonly https://www.googleapis.com/auth/gmail.send',
  googlesheets: 'https://www.googleapis.com/auth/spreadsheets https://www.googleapis.com/auth/drive',
  googledrive: 'https://www.googleapis.com/auth/drive',
  googlecalendar: 'https://www.googleapis.com/auth/calendar'
};

let scopes = [];

googleNodes.forEach(n => {
  for (const key in scopeMap) {
    if (n.type.toLowerCase().includes(key)) {
      scopes.push(scopeMap[key]);
      break;
    }
  }
});
scopes = [...new Set(scopes)].join(' ');

return [{ json: { workflowName: workflow.name, scopes } }];

const template = $input.first().json;
const userId = $json.body?.userId ?? $json.userId ?? 'unknown';
const workflow = { ...template, name: `${template.name} - User ${userId}`, active: false };
delete workflow.id;
return [{ json: { workflow, userId } }];
